effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.0,1.0)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     //#define BURST
     // #define NUM_LAYERS 5.

     mat2 Rot(float a) {
         float s=sin(a), c=cos(a);
         return mat2(c,-s,s,c);
     }

     float Star(vec2 uv, float a, float sparkle) {
         vec2 av1 = abs(uv);
      	vec2 av2 = abs(uv*Rot(a));
         vec2 av = min(av1, av2);

         vec3 col = vec3(0);
         float d = length(uv);
         float star = av1.x*av1.y;
         star = max(av1.x*av1.y, av2.x*av2.y);
         star = max(0.0, 1.0-star*1e3);

         float m = min(5.0, 1e-2/d);

         return m+pow(star, 4.0)*sparkle;
     }

     float Hash21(vec2 p) {
         p = fract(p*vec2(123.34,145.54));
         p += dot(p, p+45.23);
         return fract(p.x*p.y);
     }

     vec3 StarLayer(vec2 uv, float t, float sparkle) {
         vec2 gv = fract(uv)-.5;
         vec2 id = floor(uv);
     	vec3 col = vec3(0);
         //////////////////////////
         if( BURST ) {
         t = 0.0; }

         for(int y=-1; y<=1; y++) {
             for(int x=-1; x<=1; x++) {
                 vec2 offs = vec2(x, y);
                 float n = Hash21(id-offs);
     			vec3 N = fract(n*vec3(10,100,1000));
                 vec2 p = (N.xy-.5)*0.7;

                 float brightness = Star(gv-p+offs, n*6.2831+(t+xxg), sparkle);
                 vec3 star = brightness*vec3(COL.r+p.x, COL.g, COL.g+p.y)*N.z*N.z;
                 // vec3 star = brightness*vec3(0.6+p.x, 0.4, 0.6+p.y)*N.z*N.z;



                 star *= 1.0+sin(((t+xxh)+n)*20.0)*smoothstep(sin(t)*0.5+0.5, 1.0, fract(10.0*n));
                 // star *= 1.0+sin((t+n)*20.0)*smoothstep(sin(t)*0.5+0.5, 1.0, fract(10.0*n));

                 float d = length(gv+offs);

                 col += star*smoothstep(1.5, 0.8, d);
             }
         }
         return col;
     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     // vec2 TanRyu;
     // TanRyu = acScreenNorm; 

     vec2 TanRyu;
     TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     TanRyu.y*=acLayerSize.y/acLayerSize.x;
     TanRyu /= scale;
     TanRyu *= rot2m((0.0+angle)*0.0174533);
     TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.0,1.0)/500.0;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     TanRyu /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

         vec2 uv = TanRyu;
         // vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
         vec2 M = iMouse.xy/iResolution;

         M *= 10.0;

     	float t = autop? ( rrr? PROGRESS*0.3-(acTime*0.5) : PROGRESS*0.3+(acTime*0.5) ) : PROGRESS*0.3;

         float twirl = sin(t*0.1);
         twirl *= twirl*twirl*sin(dot(uv,uv));
         if(autor) { uv *= Rot(-t*0.2); } //AUTO ROTATE

         // uv *= 2.0+sin(t*0.05); // AUTO SCALE

         vec3 col = vec3(0);
         float speed = -0.2;
         //////////////////////////
         float burst = sin(xxa*0.05);
         float bla = sin(t+sin(t+sin(t)*0.5))*0.5+xxb;
         float d = dot(uv,uv);

         float a = atan(uv.x, uv.y);
         if( BURST ) {
         speed = 0.1;
         uv /= d;
         uv *= burst+0.2; }
         //////////////////////////

         float stp = 1.0/NUM_LAYERS;

         for(float i=0.0; i<1.0; i+=stp) {
         	float lt = autos? fract(t*speed+i) : fract(0.5*speed+i);
             float scale = mix(10.0, 0.25, lt);
             float fade = smoothstep(0.0, 0.4, lt)*smoothstep(1.0, 0.95, lt); 
             vec2 sv = uv*scale+i*134.53-M;
             //sv.x += t;
             col += StarLayer(sv, t, fade)*fade;
         }

         //////////////////////////
         if( BURST ) {
         //t = iTime*0.5;
         float burstFade = smoothstep(0.0, 0.02, abs(burst));
         float size = 0.9*sin(t)+1.0;
         size = max(size, sqrt(size));
         float fade = size/d;
         col *= mix(1.0, fade, burstFade);
         col += fade*0.2*vec3(COLB.rgb)*bla*burstFade;
         // col += fade*0.2*vec3(1.0, 0.5, 0.1)*bla*burstFade;

         t*=1.5;

         a -= M.x*0.1;
         float rays = sin(a*5.0+t*3.0)-cos(a*7.0-t);
         rays *= sin(a+t+sin(a*4.0)*10.0)*0.5+0.5;
         col += rays*bla*0.1*burstFade;
         col += 1.0-burstFade; }

         else {
         col *= 4.0; }
         //////////////////////////

         fragColor = vec4(col,1.0);

 	vec4 factor = mix(texColorX,fragColor,1.0);

     vec4 resultfinal;
       if( blendMode==0 ) {
         resultfinal = (factor * hardness) * texColor.a; }
         // resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.0)*(1.0-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.0-((1.0-(texColor.rgb/texColor.a))*(1.0-factor.rgb)),1.0) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; 
         resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
       }
     }
